import React, { useState } from 'react';
import api from '../api/axios';
import { Container, Form, Button, Alert, Row, Col } from 'react-bootstrap';

const AdminPanel = () => {
  const [studentForm, setStudentForm] = useState({
    last_name: '',
    first_name: '',
    middle_name: '',
    class: '',
    email: ''
  });
  const [teacherForm, setTeacherForm] = useState({
    last_name: '',
    first_name: '',
    middle_name: '',
    position: '',
    email: ''
  });
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');

  const handleStudentChange = (e) => {
    setStudentForm({ ...studentForm, [e.target.name]: e.target.value });
  };

  const handleTeacherChange = (e) => {
    setTeacherForm({ ...teacherForm, [e.target.name]: e.target.value });
  };

  const createStudent = async (e) => {
    e.preventDefault();
    setError('');
    setResult(null);
    try {
      const res = await api.post('/director/student', studentForm);
      setResult({ type: 'Ученик', ...res.data });
      setStudentForm({ last_name: '', first_name: '', middle_name: '', class: '', email: '' });
    } catch (err) {
      setError(err.response?.data?.error || 'Ошибка создания ученика');
    }
  };

  const createTeacher = async (e) => {
    e.preventDefault();
    setError('');
    setResult(null);
    try {
      const res = await api.post('/director/teacher', teacherForm);
      setResult({ type: 'Учитель', ...res.data });
      setTeacherForm({ last_name: '', first_name: '', middle_name: '', position: '', email: '' });
    } catch (err) {
      setError(err.response?.data?.error || 'Ошибка создания учителя');
    }
  };

  return (
    <Container className="mt-4">
      <h3>Админ-панель (Директор)</h3>
      {error && <Alert variant="danger">{error}</Alert>}
      {result && (
        <Alert variant="success">
          <strong>{result.type} создан(а)!</strong><br />
          Логин: <code>{result.login}</code><br />
          Пароль: <code>{result.password}</code><br />
          (Сообщите эти данные пользователю)
        </Alert>
      )}

      <Row>
        <Col md={6}>
          <h5>Создать ученика</h5>
          <Form onSubmit={createStudent}>
            <Form.Group className="mb-2">
              <Form.Control name="last_name" placeholder="Фамилия" value={studentForm.last_name} onChange={handleStudentChange} required />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control name="first_name" placeholder="Имя" value={studentForm.first_name} onChange={handleStudentChange} required />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control name="middle_name" placeholder="Отчество" value={studentForm.middle_name} onChange={handleStudentChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control name="class" placeholder="Класс (например, 11А)" value={studentForm.class} onChange={handleStudentChange} required />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control name="email" placeholder="Email (необязательно)" value={studentForm.email} onChange={handleStudentChange} />
            </Form.Group>
            <Button type="submit" variant="success">Создать ученика</Button>
          </Form>
        </Col>

        <Col md={6}>
          <h5>Создать учителя</h5>
          <Form onSubmit={createTeacher}>
            <Form.Group className="mb-2">
              <Form.Control name="last_name" placeholder="Фамилия" value={teacherForm.last_name} onChange={handleTeacherChange} required />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control name="first_name" placeholder="Имя" value={teacherForm.first_name} onChange={handleTeacherChange} required />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control name="middle_name" placeholder="Отчество" value={teacherForm.middle_name} onChange={handleTeacherChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control name="position" placeholder="Должность (например, Учитель математики)" value={teacherForm.position} onChange={handleTeacherChange} required />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control name="email" placeholder="Email (необязательно)" value={teacherForm.email} onChange={handleTeacherChange} />
            </Form.Group>
            <Button type="submit" variant="primary">Создать учителя</Button>
          </Form>
        </Col>
      </Row>
    </Container>
  );
};

export default AdminPanel;
